import json

def predict_ict_risk(text):
    # Define the ITC EBA definition
    ict_risks = {
        "ICT Availability Risk": ["availability", "unavailability", "hardware failure", "software issues", "cyber-attacks"],
        "ICT Security Risk": ["security", "access", "use", "disclosure", "modification", "destruction", "unauthorized", "inadequate access controls", "encryption"],
        "ICT Change Risk": ["change", "update", "deployment", "testing", "bug", "disruption", "security vulnerability"],
        "ICT Outsourcing Risk": ["outsourcing", "relying", "third-party", "service provider", "critical", "services", "potential loss of control"],
        "ICT Data Integrity Risk": ["data", "information", "processing", "methods", "accuracy", "completeness", "alteration", "undetected", "software flaw"],
        "ICT Compliance Risk": ["compliance", "laws", "regulations", "contractual obligations", "failure to comply", "penalties", "reputation"]
    }

    # Check if the text is ambiguous
    if text.lower() in ["ambiguous", "unclear"]:
        return {"prediction": "Not applicable", "reasoning": "The text is ambiguous and cannot be classified."}

    # Check each ITC risk class
    for risk, keywords in ict_risks.items():
        if any(keyword.lower() in text.lower() for keyword in keywords):
            return {"prediction": risk, "reasoning": f"The text suggests a risk of {risk}."}

    # If no risk class is applicable, return a default message
    return {"prediction": "Not applicable", "reasoning": "No ITC risk class is applicable."}

